// HasAccount filters parents that have a matching Account using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Accounts).
func (w purchasePaymentWhereR[Q]) HasAccount(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Accounts.NameExpr()),
		sm.Where(Accounts.Columns.HouseholdID.EQ(w.cols.HouseholdID)),
		sm.Where(Accounts.Columns.ID.EQ(w.cols.AccountID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasPurchase filters parents that have a matching Purchase using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Purchases).
func (w purchasePaymentWhereR[Q]) HasPurchase(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Purchases.NameExpr()),
		sm.Where(Purchases.Columns.HouseholdID.EQ(w.cols.HouseholdID)),
		sm.Where(Purchases.Columns.ID.EQ(w.cols.PurchaseID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

func (o *PurchasePayment) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Account":
		rel, ok := retrieved.(*Account)
		if !ok {
			return fmt.Errorf("purchasePayment cannot load %T as %q", retrieved, name)
		}

		o.R.Account = rel
		o.R.Loaded.Account = true

		if rel != nil {
			rel.R.PurchasePayments = PurchasePaymentSlice{o}
		}
		return nil
	case "Purchase":
		rel, ok := retrieved.(*Purchase)
		if !ok {
			return fmt.Errorf("purchasePayment cannot load %T as %q", retrieved, name)
		}

		o.R.Purchase = rel
		o.R.Loaded.Purchase = true

		if rel != nil {
			rel.R.PurchasePayments = PurchasePaymentSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("purchasePayment has no relationship %q", name)
	}
}

