// LoadAccount loads the purchasePayment's Account into the .R struct
func (o *PurchasePayment) LoadAccount(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Account = nil
	o.R.Loaded.Account = false

	related, err := o.Account(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.PurchasePayments = PurchasePaymentSlice{o}

	o.R.Account = related
	o.R.Loaded.Account = true
	return nil
}

// LoadAccount loads the purchasePayment's Account into the .R struct
func (os PurchasePaymentSlice) LoadAccount(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	accounts, err := os.Account(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Account = nil
		o.R.Loaded.Account = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range accounts {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.AccountID == rel.ID) {
				continue
			}

			rel.R.PurchasePayments = append(rel.R.PurchasePayments, o)

			o.R.Account = rel
			break
		}
	}

	return nil
}

