type purchasePaymentJoins[Q dialect.Joinable] struct {
	typ      string
	Account  modAs[Q, accountColumns]
	Purchase modAs[Q, purchaseColumns]
}

func (j purchasePaymentJoins[Q]) aliasedAs(alias string) purchasePaymentJoins[Q] {
	return buildPurchasePaymentJoins[Q](buildPurchasePaymentColumns(alias), j.typ)
}

func buildPurchasePaymentJoins[Q dialect.Joinable](cols purchasePaymentColumns, typ string) purchasePaymentJoins[Q] {
	return purchasePaymentJoins[Q]{
		typ: typ,
		Account: modAs[Q, accountColumns]{
			c: Accounts.Columns,
			f: func(to accountColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Accounts.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.AccountID),
					))
				}

				return mods
			},
		},
		Purchase: modAs[Q, purchaseColumns]{
			c: Purchases.Columns,
			f: func(to purchaseColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Purchases.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.PurchaseID),
					))
				}

				return mods
			},
		},
	}
}
